#!/usr/bin/env python3
import csv, json, os, re, sys, configparser
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WD = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


def cents(s):
    return int((Decimal(str(s).strip()) * 100).to_integral_value())


def pnum(s):
    d = re.sub(r"\D", "", s or "")
    return int(d) if d else None


def pdate(s):
    return date.fromisoformat(s.strip())


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return [{(k or "").strip(): (v or "").strip() for k, v in r.items()} for r in csv.DictReader(f)]


def parse_offset(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s)
    sign = -1 if m.group(1) == "-" else 1
    return timedelta(minutes=sign * (int(m.group(2)) * 60 + int(m.group(3))))


def parse_utc(s):
    return datetime.strptime(s.strip(), "%Y-%m-%dT%H:%MZ")  # naive UTC


def main(inp, outp):
    cp = configparser.ConfigParser(interpolation=None)
    cp.optionxform = str
    with open(os.path.join(inp, "policy.ini"), encoding="utf-8-sig") as f:
        cp.read_file(f)
    library = cp["statement"]["library"].strip()
    pstart = pdate(cp["statement"]["period_start"])
    pend = pdate(cp["statement"]["period_end"])
    base_off = parse_offset(cp["clock"]["offset"])
    changes = []
    for part in cp["clock"].get("changes", "").split(";"):
        part = part.strip()
        if part:
            t, o = part.split()
            changes.append((parse_utc(t), parse_offset(o)))
    changes.sort()

    items = {}
    cats = {}
    for sec in cp.sections():
        low = sec.lower()
        if low.startswith("item:"):
            s = cp[sec]
            items[low[5:].strip()] = dict(
                name=sec[5:].strip(), loan_days=int(s["loan_days"]), renewals=int(s["renewals"]),
                grace=int(s["grace_days"]), daily=cents(s["daily"]), cap=cents(s["loan_cap"]))
        elif low.startswith("category:"):
            s = cp[sec]
            sc = s["statement_cap"].strip()
            cats[low[9:].strip()] = dict(
                name=sec[9:].strip(), cap=None if sc.lower() == "none" else cents(sc),
                discount=int(s["discount"]),
                exempt={x.strip().lower() for x in s.get("exempt", "").split(",") if x.strip()})

    branches = read_csv(os.path.join(inp, "branches.csv"))
    open_days = {}
    for b in branches:
        open_days[b["branch"]] = {w.lower() for w in b["open_days"].split()}
    cal = {}
    for r in read_csv(os.path.join(inp, "calendar.csv")):
        d = r["date"]
        if ".." in d:
            a, z = d.split("..")
            a, z = pdate(a), pdate(z)
        else:
            a = z = pdate(d)
        cal.setdefault(r["branch"], []).append((a, z, r["status"].strip().lower()))

    def is_open(br, day):
        for key in (br, "*"):
            for a, z, st in cal.get(key, []):
                if a <= day <= z:
                    return st == "open"
        return WD[day.weekday()].lower() in open_days.get(br, set())

    def next_open(br, day):
        for _ in range(4000):
            if is_open(br, day):
                return day
            day += timedelta(days=1)
        return day

    patrons = {}
    for r in read_csv(os.path.join(inp, "patrons.csv")):
        patrons.setdefault(pnum(r["patron"]), []).append((pdate(r["since"]), r["category"], r["patron"]))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def patron_row(pn, day):
        best = None
        for row in patrons.get(pn, []):
            if row[0] <= day:
                best = row
        return best or (patrons[pn][0] if patrons.get(pn) else None)

    def cat_of(pn, day):
        row = patron_row(pn, day)
        return cats[row[1].strip().lower()], row

    # events
    def local_from_instant(s):
        s = s.strip()
        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        utc = (dt - dt.utcoffset()).replace(tzinfo=None)
        off = base_off
        for t, o in changes:
            if utc >= t:
                off = o
        return utc + off

    events = {}
    exdir = os.path.join(inp, "exports")
    for fn in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, fn)
        low = fn.lower()
        if not os.path.isfile(path):
            continue
        recs = []
        if low.endswith(".csv"):
            for r in read_csv(path):
                t = r.get("time", "")
                if t:
                    r["_local"] = datetime.strptime(t[:16], "%Y-%m-%d %H:%M")
                recs.append(r)
        elif low.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    r = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                    if r.get("at"):
                        r["_local"] = local_from_instant(r["at"])
                    recs.append(r)
        for r in recs:
            if r.get("event") and r["event"] not in events:
                events[r["event"]] = r

    voided = {r["target"] for r in events.values() if r.get("type", "").lower() == "void" and r.get("target")}
    by_loan = {}
    for r in events.values():
        ty = r.get("type", "").lower()
        if ty in ("checkout", "renew", "return") and r["event"] not in voided and "_local" in r:
            by_loan.setdefault(r.get("loan", ""), []).append((r["_local"], ty, r))

    loans = []
    for lid, evs in by_loan.items():
        cos = [e for e in evs if e[1] == "checkout"]
        if not cos:
            continue
        co = cos[0][2]
        cod = co["_local"].date()
        if cod > pend:
            continue
        it = items[co["item_type"].lower()]
        br = co["branch"]
        pn = pnum(co["patron"])
        due = next_open(br, cod + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for lt, ty, r in sorted((e for e in evs if e[1] != "checkout"), key=lambda e: e[0]):
            d = lt.date()
            if ty == "renew":
                if d <= due and nren < it["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=it["loan_days"]))
            else:
                ret = d - timedelta(days=1) if r.get("via", "").lower() == "dropbox" else d
                break
        if ret is not None and ret < pstart:
            continue
        end = pend if (ret is None or ret > pend) else ret
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od == 0:
            continue
        charged = od if od > it["grace"] else 0
        cat, _ = cat_of(pn, cod)
        fee = charged * it["daily"]
        if it["name"].lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, it["cap"])
        fee = (fee * (100 - cat["discount"]) + 50) // 100
        loans.append(dict(loan=lid, item=co.get("item", ""), item_type=it["name"], branch=br,
                          checkout=cod, due=due, returned=ret if (ret is not None and ret <= pend) else None,
                          overdue_days=od, charged_days=charged, assessed=fee, pn=pn))

    waivers = [w for w in read_csv(os.path.join(inp, "waivers.csv")) if w["status"].lower() == "active"]

    by_p = {}
    for l in loans:
        by_p.setdefault(l["pn"], []).append(l)
    statements = []
    for pn in sorted(by_p, key=lambda x: (x is None, x)):
        ls = by_p[pn]
        cat, row = cat_of(pn, pend)
        for l in ls:
            ws = [w for w in waivers if pnum(w["patron"]) == pn and (w["loan"] == "*" or w["loan"] == l["loan"])]
            if any(w["value"].lower() == "full" for w in ws):
                waived = l["assessed"]
            else:
                waived = min(l["assessed"], sum(cents(w["value"]) for w in ws))
            l["waived"] = waived
            l["net"] = l["assessed"] - waived
            l["capped"] = 0
        if cat["cap"] is not None:
            excess = sum(l["net"] for l in ls) - cat["cap"]
            for l in sorted(ls, key=lambda l: (l["due"], l["loan"]), reverse=True):
                if excess <= 0:
                    break
                g = min(excess, l["net"])
                l["capped"] = g
                excess -= g
        ls.sort(key=lambda l: (l["due"], l["loan"]))
        out = []
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
            out.append({"loan": l["loan"], "item": l["item"], "item_type": l["item_type"], "branch": l["branch"],
                        "checkout": l["checkout"].isoformat(), "due": l["due"].isoformat(),
                        "returned": l["returned"].isoformat() if l["returned"] else None,
                        "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                        "assessed": l["assessed"], "waived": l["waived"], "capped": l["capped"],
                        "billed": l["billed"]})
        st = {"patron": row[2], "category": cat["name"], "loans": out}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(o[k] for o in out)
        statements.append(st)

    summary = []
    for b in branches:
        ls = [o for s in statements for o in s["loans"] if o["branch"] == b["branch"]]
        e = {"branch": b["branch"], "loans": len(ls), "charged_days": sum(o["charged_days"] for o in ls)}
        for k in ("assessed", "waived", "capped", "billed"):
            e[k] = sum(o[k] for o in ls)
        summary.append(e)

    res = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": statements, "branches": summary}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
