    library = cp["statement"]["library"].strip()
    pstart = pdate(cp["statement"]["period_start"])
    pend = pdate(cp["statement"]["period_end"])
    base_off = parse_offset(cp["clock"]["offset"])
    changes = []
    for part in cp["clock"].get("changes", "").split(";"):
        part = part.strip()
        if part:
            t, o = part.split()
            changes.append((parse_utc(t), parse_offset(o)))
    changes.sort()

    items = {}
    cats = {}
    for sec in cp.sections():
